import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NamespaceResolver.isSealed()
 */
public class NamespaceResolver_isSealed_TriageGen0Test {





    @Test
    public void testIsSealed_WithParent() {
        // Given a parent resolver that is sealed
        NamespaceResolver parent = new NamespaceResolver();
        parent.seal();

        // When creating a child resolver using the parent constructor
        NamespaceResolver child = new NamespaceResolver(parent);

        // Then the child's sealed status depends on its own internal state 
        // (Based on the provided API, seal() affects the instance itself)
        // We verify the child is initialized correctly.
        assertFalse("Child resolver should not be sealed by default even if parent is", child.isSealed());

        child.seal();
        assertTrue("Child resolver should be sealable independently", child.isSealed());
    }


}

